Given an array arr[], the task is to find the maximum distance between two occurrences of any element. If no element occurs twice, return 0.Examples:  Input: arr = [1, 1, 2, 2, 2, 1]Output: 5Explanation: distance for 1 is: 5-0 = 5, distance for 2 is: 4-2 = 2, So max distance is 5.Input : arr[] = [3, 2, 1, 2, 1, 4, 5, 8, 6, 7, 4, 2]Output: 10Explanation : Max distance for 2 is 11-1 = 10, max distance for 1 is 4-2 = 2 and max distance for 4 is 10-5 = 5  Input: arr[] = [1, 2, 3, 6, 5, 4]Output: 0Explanation: No element has two occurrence, so maximum distance = 0.Try It YourselfTable of Content[Naive Approach] Exploring all pairs - O(n^2) Time and O(1) Space[Expected Approach] Using Hash Map or Dictionary - O(n) Time and O(n) Space[Naive Approach] Exploring all pairs - O(n^2) Time and O(1) SpaceOne by one, pick each element from the array and find its first and last occurrence in the array and take the difference between the first and last occurrence for maximum distance.
            C++

    // C++ Program to find max distance between two occurrences
// in array by exploring all pairs

#include <iostream>
#include <vector>
using namespace std;

// function to find the maximum distance
int maxDistance(vector<int>& arr) {
    int res = 0;
    for (int i = 0; i < arr.size() - 1; i++) {
        for (int j = i + 1; j < arr.size(); j++) {

            // check if two elements are equal
            if (arr[i] == arr[j]) {

              // calculate the distance and update res
               res = max(res, j - i);
            }
        }
    }
    return res;
}

// Driver code
int main() {
    vector<int> arr = {1, 2, 4, 1, 3, 4, 2, 5, 6, 5};
    cout << maxDistance(arr) << endl;
    return 0;
}


