[Expected Approach] Using Hash Map or Dictionary - O(n) Time and O(n) SpaceAn efficient solution to this problem is to use hashing. The idea is to traverse the input array and store the index of the first occurrence in a hash map. For every other occurrence, find the difference between the index and the first index stored in the hash map. If the difference is more than the result so far, then update the result.
            C++

    // C++ Program to find max distance between two occurrences
// in array using hashing

#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int maxDistance(vector<int>& arr) {

    // Stores element to first index mapping
    unordered_map<int, int> mp; 

    int res = 0;

    for (int i = 0; i < arr.size(); i++) {

        // If this is the first occurrence of 
        // the element, store its index
        if (mp.find(arr[i]) == mp.end())
            mp[arr[i]] = i;

        // Else update max distance
        else
            res = max(res, i - mp[arr[i]]);
    }

    return res;
}

int main() {
    vector<int> arr = {1, 1, 2, 2, 2, 1};
    cout << maxDistance(arr);
    return 0;
}


